import{_ as i,o as a,c as n,a0 as o}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Skill: /api-spec","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/api-spec.md","filePath":"references/skills/api-spec.md"}'),c={name:"references/skills/api-spec.md"};function t(l,e,d,r,s,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="skill-api-spec" tabindex="-1">Skill: <code>/api-spec</code> <a class="header-anchor" href="#skill-api-spec" aria-label="Permalink to &quot;Skill: `/api-spec`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>api-spec</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/api-spec &lt;page-id/slug&gt;</code></li><li>Chỉ chạy <strong>SAU KHI</strong> FE Spec đã được tạo và các actions cần gọi API đã được liệt kê (Trong <code>ir/design.yaml</code>). Không chạy độc lập trước khi có giao diện.</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc mảng <code>design.actions</code> hoặc <code>apiRefs</code> từ <code>ir/design.yaml</code> của trang tương ứng.</li><li>Phải quét qua các API dùng chung (<code>common/yaml/</code>) hoặc các api của màn hình lân cận để tìm cơ hội tái sử dụng (<code>#reuse-api</code>).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Nếu API là mới hoàn toàn: Tạo thư mục <code>api/&lt;seq&gt;/</code> và sinh file <code>01-backend-spec.yaml</code> theo đúng chuẩn (cấu trúc mẫu: <a href="../../../templates/shared/backend-api.bundle.yaml"><code>backend-api.bundle.yaml</code></a>; sau init có bản trong <code>.flowgrid/templates/</code>).</li><li>Nếu API gọi lại đồ cũ: Đánh tag <code>#reuse-api</code> và tham chiếu <code>reuseFrom:</code> trên file bundle hiện tại, <strong>KHÔNG</strong> sinh ra bộ 3 file api mới (<code>01</code>, <code>02</code>, <code>03</code>).</li><li>File <code>02-openapi.yaml</code> (nếu sinh file 01 mới, thì sau đó chạy lệnh <code>flowgrid openapi_gen</code>).</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Chuyên dùng để thiết kế hợp đồng Backend API (Backend API Contract).</li><li><strong>Quy tắc tái sử dụng (Reuse First):</strong> Luôn ưu tiên dùng lại API đã có bằng thẻ <code>#reuse-api</code>. Tránh tình trạng sinh ra hàng loạt API rác, thừa thãi cho các tác vụ giống nhau (như lấy dropdown list).</li><li><strong>Quy tắc đặt tên URI tường minh (Explicit URI Naming):</strong> Cấm đoán việc dùng RESTful mù mờ. Luôn phải gắn hậu tố rõ ràng ở đuôi API (VD: <code>/create</code>, <code>/{id}/update</code>, <code>/{id}/delete</code>, <code>/{id}/detail</code>).</li><li><strong>Phân loại lỗi (Endpoint Error Storming):</strong> Ép buộc phải định nghĩa rõ API này có thể gặp lỗi gì (404 Not Found, 403 IDOR, 422 Validation, 409 Conflict) bằng các thẻ <code>#err:*</code> và <code>errorStorming</code>.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Bắt buộc phải có <code>ir/design.yaml</code> (Kết quả của <code>/spec</code> hoặc <code>/update-spec</code>).</li><li><strong>Sau đó:</strong> Chạy lệnh sinh <code>02-openapi.yaml</code> (Skill <code>/openapi</code>). Bị review gắt gao bởi <code>/grill-api-spec</code>.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li><strong>Luật AskQuestion Tech Debt:</strong> Nếu thông tin truyền tải bị thiếu, Agent bắt buộc phải hỏi Member bằng Form AskQuestion và phải có tuỳ chọn <code>&quot;Log as Tech Debt&quot;</code>. Trả lời &quot;Tech Debt&quot; sẽ sinh file <code>QA-&lt;feature.id&gt;-NNNN</code>. Cấm để lại cờ <code>openQuestions</code> bên trong file YAML.</li><li><strong>KHÔNG SINH FILE MARKDOWN:</strong> <code>api-spec</code> chỉ sinh YAML. Việc render ra giao diện <code>.md</code> cho người đọc là nhiệm vụ bộ docs (<code>flowgrid render</code> / <code>pnpm flowgrid:render</code>).</li><li>Đọc template mẫu <a href="../../../templates/shared/backend-api.bundle.yaml"><code>templates/shared/backend-api.bundle.yaml</code></a> (hoặc bản trong <code>.flowgrid/templates/</code> sau init) trước khi gen YAML mới.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api-spec</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const g=i(c,[["render",t]]);export{u as __pageData,g as default};
